mapper.select:
select * from ST_RNFL_RMODE


        and STCD = #{STCD}


         and TM >= to_date(#{stime}, 'YYYY-MM-DD HH24:MI:SS') 


         and TM <= to_date(#{etime}, 'YYYY-MM-DD HH24:MI:SS') 


ORDER BY TM ASC

    limit #{startindex},#{pagesize}

mapper.update:
update ST_RNFL_RMODE
DRP = #{DRP}, INTV = #{INTV}, TEMP = #{TEMP}, HUMIDITY = #{HUMIDITY}, WINDDIR = #{WINDDIR}, WINDSPEED = #{WINDSPEED}, WEATHERCODE = #{WEATHERCODE}, AIRPRESSURE = #{AIRPRESSURE}, TYPE = #{TYPE},
where STCD = #{STCD} AND YBTM = #{YBTM} AND TM = #{TM} AND FPDR = #{FPDR}

mapper.select:
SELECT STCD, YBTM, TM, DRP, INTV, TEMP, HUMIDITY, WINDDIR, WINDSPEED, WEATHERCODE, AIRPRESSURE, TYPE, FPDR FROM ( SELECT STCD, YBTM, TM, DRP, INTV, TEMP, HUMIDITY, WINDDIR, WINDSPEED, WEATHERCODE, AIRPRESSURE, TYPE, FPDR, ROW_NUMBER() OVER(PARTITION BY STCD, TM ORDER BY YBTM DESC) as rn FROM ST_RNFL_RMODE
and STCD in
#{item}
and TM >= to_date(#{stime}, 'YYYY-MM-DD HH24:MI:SS')
and TM <= to_date(#{etime}, 'YYYY-MM-DD HH24:MI:SS')
and FPDR in
#{item}
and TYPE = #{type}
) t WHERE t.rn = 1 ORDER BY t.TM
